// (e.g. `eslint apps/floor/` in a subdir). Warn once and skip rather than
// report thousands of misleading errors.
function warnMissingCorpusOnce(specsRoot, roots) {
    if (warnedMissingCorpus.has(specsRoot)) {
        return;
    }
    warnedMissingCorpus.add(specsRoot);
    console.warn(`require-spec-link: no ${roots.join("/")} directory under ${specsRoot} — ` +
        "run eslint from the repo root (or pass options.specsRoot). Skipping the spec-link check.");
}
function testName(sourceCode, first) {
    return first.type === "Literal"
        ? String(first.value)
        : sourceCode.getText(first);
}
function reportUnlinked(context, node, corpus) {
    if (!isNamedTestCall(node)) {
        return;
    }
    const startLine = node.loc.start.line;
    if (isLinked(corpus.entry, startLine, node.loc.end.line)) {
        return;
    }
    context.report({
        node: node.callee,
        messageId: "unlinkedTest",
        data: {
            name: testName(context.sourceCode, node.arguments[0]),
            file: corpus.relPath,
            line: String(startLine),
            roots: corpus.roots.map((root) => `${root}/**/*.md`).join(" or "),
        },
    });
}
export default {
    meta: {
        type: "problem",
        docs: {
            description: "require every test to be linked from a spec or ADR via an inline ([validated by](test.ts#Lline)) link. The spec/adr corpus is read once per process and memoized, so in a long-lived ESLint server (VS Code extension, --watch) a newly added link is not seen until the server restarts; a one-shot `eslint`/CI run always reads fresh.",
        },
        schema: [
            {
                type: "object",
                properties: {
                    specsRoot: { type: "string" },
                    roots: { type: "array", items: { type: "string" } },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            unlinkedTest: "Test {{name}} has no spec link — add an inline ([validated by]({{file}}#L{{line}})) to the statement it validates in a {{roots}} markdown file (or, if this test isn't tied to a spec statement, it may not belong in the traceable suite).",
        },
    },
    create(context) {
        // Match the same predicate `buildLinkIndex` uses to keep validated-by links
        // (isTestFile: .test./.spec./__tests__/…), so a linkable test can't escape
        // the rule on a naming variant.
        if (!isTestFile(toPosix(context.filename))) {
            return {};
        }
        const options = context.options[0] ?? {};
        const specsRoot = options.specsRoot ?? context.cwd;
        const roots = options.roots ?? ["specs", "adrs"];
        if (!corpusExists(specsRoot, roots)) {
            warnMissingCorpusOnce(specsRoot, roots);
            return {};
        }
        const relPath = toPosix(path.relative(specsRoot, context.filename));
        const corpus = {
            entry: getIndex(specsRoot, roots).get(relPath),
            relPath,
            roots,
        };
        return {
            CallExpression: (node) => reportUnlinked(context, node, corpus),
        };
    },
};

